const PRACTICE_CACHE_PREFIX='lagrey_practice_sessions_',PRACTICE_DIRTY_PREFIX='lagrey_practice_dirty_';
let practiceContextState={trackId:'',itemId:'',songId:null,eventId:null},practiceSyncPromise=null;
function practiceOwner(){const state=cloudState();if(state?.mode==='ministry'&&state.user?.id)return String(state.user.id);const profile=savedAppProfile();return profile?.cloud&&profile?.id?String(profile.id):'guest'}
const practiceCacheKey=owner=>PRACTICE_CACHE_PREFIX+owner,practiceDirtyKey=owner=>PRACTICE_DIRTY_PREFIX+owner;
function normalizePracticeSession(session){const role=['voice','guitar','piano','bass','drums','all','none'].includes(String(session?.instrumentRole||''))?String(session.instrumentRole):'none',duration=session?.durationMinutes==null||session.durationMinutes===''?null:Number(session.durationMinutes);return{id:String(session?.id||''),practicedAt:String(session?.practicedAt||new Date().toISOString()),durationMinutes:Number.isInteger(duration)&&duration>0&&duration<=720?duration:null,instrumentRole:role,trackId:String(session?.trackId||''),itemId:String(session?.itemId||''),songId:session?.songId==null?null:Number(session.songId),eventId:session?.eventId?String(session.eventId):null,note:String(session?.note||'').slice(0,2000)}}
function practiceSessions(){const owner=practiceOwner(),rows=(readLocalJSON(practiceCacheKey(owner),[])||[]).map(normalizePracticeSession).filter(item=>item.id);return rows.sort((a,b)=>String(b.practicedAt).localeCompare(String(a.practicedAt)))}
function savePracticeCache(rows){writeLocalJSON(practiceCacheKey(practiceOwner()),(rows||[]).map(normalizePracticeSession).filter(item=>item.id))}
function practiceMarkDirty(session,deleted=false){const owner=practiceOwner();if(owner==='guest')return;const dirty=readLocalJSON(practiceDirtyKey(owner),{});dirty[session.id]=deleted?{deleted:true}:{session:normalizePracticeSession(session)};writeLocalJSON(practiceDirtyKey(owner),dirty)}
function practiceRoleLabel(role){const item=EVENT_MUSIC[role];if(item)return eventMusicLabel(role);return role==='all'?appText('🎼 Múltiples funciones','🎼 Multiple roles'):appText('🎵 General','🎵 General')}
function practiceContextLabel(session){if(session.trackId){const course=ACADEMY_COURSES.find(item=>item.id===session.trackId);if(course)return academyPick(course.title)}if(session.songId){const song=songs.find(item=>Number(item.id)===Number(session.songId));if(song)return song.title}if(session.eventId){const event=getEvents().find(item=>String(item.id)===String(session.eventId));if(event)return event.title}return''}
function practiceDateText(value){try{return new Intl.DateTimeFormat(appLocale(),{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(value))}catch{return String(value||'')}}
function practiceWeekStats(){const cutoff=Date.now()-7*86400000,rows=practiceSessions().filter(item=>new Date(item.practicedAt).getTime()>=cutoff),minutes=rows.reduce((sum,item)=>sum+(item.durationMinutes||0),0);return{sessions:rows.length,minutes}}
function renderAcademyPractice(){const box=$('academyPractice');if(!box)return;const rows=practiceSessions(),stats=practiceWeekStats(),recent=rows.slice(0,5);box.innerHTML=`<section class="practice-panel practice-panel-compact"><div class="practice-compact-main"><div class="practice-compact-icon">🕒</div><div><b>${appText('Mi práctica','My practice')}</b><small>${stats.sessions} ${appText('sesiones esta semana','sessions this week')}${stats.minutes?' · '+stats.minutes+' min':''}</small></div><button class="btn primary" data-practice-open>＋ ${appText('Registrar','Log')}</button></div>${recent.length?`<details class="practice-history-fold"><summary>${appText('Actividad reciente','Recent activity')} <span>›</span></summary><div class="practice-recent">${recent.map(session=>{const context=practiceContextLabel(session);return`<article class="practice-row"><div><b>${esc(practiceRoleLabel(session.instrumentRole))}${session.durationMinutes?` · ${session.durationMinutes} min`:''}</b><small>${esc(practiceDateText(session.practicedAt))}${context?` · ${esc(context)}`:''}</small>${session.note?`<p>${esc(session.note)}</p>`:''}</div><button class="tiny-btn" data-practice-delete="${esc(session.id)}" aria-label="${appText('Eliminar práctica','Delete practice')}">×</button></article>`}).join('')}</div></details>`:''}</section>`;box.querySelector('[data-practice-open]')?.addEventListener('click',()=>openPracticeModal());box.querySelectorAll('[data-practice-delete]').forEach(button=>button.onclick=()=>deletePracticeSessionLocal(button.dataset.practiceDelete))}
function practiceModalStatus(message,ok=false){const el=$('practiceStatus');if(!el)return;el.textContent=message||'';el.classList.toggle('profile-ok',!!ok)}
function openPracticeModal(context={}){practiceContextState={trackId:String(context.trackId||''),itemId:String(context.itemId||''),songId:context.songId==null?null:Number(context.songId),eventId:context.eventId?String(context.eventId):null};const role=$('practiceRole'),pref=academyPreferredInstrument();if(role)role.value=['voice','guitar','piano','bass','drums'].includes(pref)?pref:'none';if($('practiceDuration'))$('practiceDuration').value='';if($('practiceNote'))$('practiceNote').value='';if($('practiceModalTitle'))$('practiceModalTitle').textContent=appText('🕒 Registrar práctica','🕒 Log practice');if($('practiceModalSub'))$('practiceModalSub').textContent=appText('Guarda una sesión privada para recordar tu progreso.','Save a private session to remember your progress.');if($('practiceRoleLabel'))$('practiceRoleLabel').firstChild.textContent=appText('Función / instrumento','Role / instrument');if($('practiceDurationLabel'))$('practiceDurationLabel').firstChild.textContent=appText('Duración aproximada (minutos)','Approximate duration (minutes)');if($('practiceNoteLabel'))$('practiceNoteLabel').firstChild.textContent=appText('Nota opcional','Optional note');if($('practiceSaveBtn'))$('practiceSaveBtn').textContent=appText('Guardar práctica','Save practice');const contextEl=$('practiceContext'),label=practiceContextLabel({...practiceContextState});if(contextEl){contextEl.textContent=label?appText('Relacionado con: ','Related to: ')+label:'';contextEl.classList.toggle('hidden',!label)}practiceModalStatus('');$('practiceModal')?.classList.remove('hidden')}
function closePracticeModal(){$('practiceModal')?.classList.add('hidden')}
async function savePracticeFromModal(){const durationText=String($('practiceDuration')?.value||'').trim(),duration=durationText?Number(durationText):null,note=String($('practiceNote')?.value||''),role=String($('practiceRole')?.value||'none');if(duration!==null&&(!Number.isInteger(duration)||duration<1||duration>720)){practiceModalStatus(appText('La duración debe estar entre 1 y 720 minutos.','Duration must be between 1 and 720 minutes.'));return}if(note.length>2000){practiceModalStatus(appText('La nota es demasiado larga.','The note is too long.'));return}const session=normalizePracticeSession({id:window.crypto?.randomUUID?.()||('practice-'+Date.now()+'-'+Math.random().toString(36).slice(2)),practicedAt:new Date().toISOString(),durationMinutes:duration,instrumentRole:role,...practiceContextState,note});const rows=practiceSessions();rows.unshift(session);savePracticeCache(rows);practiceMarkDirty(session,false);renderAcademyPractice();closePracticeModal();toast(appText('Práctica guardada.','Practice saved.'));syncPracticeSessions()}
function deletePracticeSessionLocal(id){const session=practiceSessions().find(item=>item.id===String(id));if(!session)return;if(!confirm(appText('¿Eliminar este registro de práctica?','Delete this practice entry?')))return;savePracticeCache(practiceSessions().filter(item=>item.id!==session.id));practiceMarkDirty(session,true);renderAcademyPractice();syncPracticeSessions()}
async function syncPracticeSessions(){const state=cloudState(),owner=practiceOwner();if(state?.mode!=='ministry'||owner==='guest'||!state.data?.getPracticeSessions||!state.data?.savePracticeSession||!state.data?.deletePracticeSession)return false;if(practiceSyncPromise)return practiceSyncPromise;practiceSyncPromise=(async()=>{try{const dirty=readLocalJSON(practiceDirtyKey(owner),{});for(const [id,change] of Object.entries(dirty||{})){if(change?.deleted)await state.data.deletePracticeSession(id);else if(change?.session)await state.data.savePracticeSession(change.session);delete dirty[id]}writeLocalJSON(practiceDirtyKey(owner),dirty);const rows=await state.data.getPracticeSessions(80);savePracticeCache(rows);if(!$('academyView')?.classList.contains('hidden'))renderAcademyPractice();return true}catch(error){console.warn('[La Grey práctica] sincronización pendiente',error);return false}finally{practiceSyncPromise=null}})();return practiceSyncPromise}
